# PTX source for the hinge‑loss kernel (float16 inputs, float16 output)
PTX_SOURCE = r"""
.version 7.2
.target sm_80
.address_size 64

.visible .entry hinge_loss_kernel (
    .param .u64 pred_ptr,
    .param .u64 targ_ptr,
    .param .u64 out_ptr,
    .param .u32 N
)
{
    // -----------------------------------------------------------------
    // Load kernel parameters
    // -----------------------------------------------------------------
    .reg .u64 %pred, %targ, %out;
    .reg .u32 %n;
    ld.param.u64 %pred, [pred_ptr];
    ld.param.u64 %targ, [targ_ptr];
    ld.param.u64 %out,  [out_ptr];
    ld.param.u32 %n,    [N];

    // -----------------------------------------------------------------
    // Built‑in thread/block identifiers
    // -----------------------------------------------------------------
    .reg .u32 %tid_x, %blockIdx_x, %blockDim_x, %gridDim_x;
    mov.u32 %tid_x,      %tid.x;      // threadIdx.x
    mov.u32 %blockIdx_x, %ctaid.x;    // blockIdx.x
    mov.u32 %blockDim_x, %ntid.x;     // blockDim.x
    mov.u32 %gridDim_x,  %nctaid.x;   // gridDim.x

    // Global thread index and stride
    .reg .u32 %global_tid, %stride;
    mad.lo.u32 %global_tid, %blockIdx_x, %blockDim_x, %tid_x;
    mul.lo.u32 %stride, %blockDim_x, %gridDim_x;

    // -----------------------------------------------------------------
    // Per‑thread accumulation (float32)
    // -----------------------------------------------------------------
    .reg .f32 %local_sum;
    mov.f32 %local_sum, 0f0;

    .reg .u32 %i;
    mov.u32 %i, %global_tid;

LOOP_START:
    setp.ge.u32 %p_exit, %i, %n;
    @%p_exit bra LOOP_END;

    // byte offset = i * 2 (half = 2 bytes)
    .reg .u64 %offset;
    mul.wide.u32 %offset, %i, 2;

    // Load half values
    .reg .u16 %h_pred, %h_targ;
    ld.global.u16 %h_pred, [%pred + %offset];
    ld.global.u16 %h_targ, [%targ + %offset];

    // Convert to float32
    .reg .f32 %f_pred, %f_targ;
    cvt.f32.f16 %f_pred, %h_pred;
    cvt.f32.f16 %f_targ, %h_targ;

    // val = 1 - f_pred * f_targ
    .reg .f32 %prod, %val;
    mul.f32 %prod, %f_pred, %f_targ;
    sub.f32 %val, 1.0f, %prod;

    // clamp at zero
    .reg .pred %p_neg;
    setp.lt.f32 %p_neg, %val, 0f0;
    @%p_neg mov.f32 %val, 0f0;

    // accumulate
    add.f32 %local_sum, %local_sum, %val;

    // i += stride
    add.u32 %i, %i, %stride;
    bra LOOP_START;
LOOP_END:

    // -----------------------------------------------------------------
    // Shared memory reduction (single block)
    // -----------------------------------------------------------------
    .shared .align 4 .b8 shmem[4096];          // 1024 threads * 4 bytes
    .reg .u64 %shmem_addr;
    mul.wide.u32 %shmem_addr, %tid_x, 4;       // address of this thread's slot
    st.shared.f32 [%shmem_addr], %local_sum;

    bar.sync 0;                                 // __syncthreads()

    // reduction loop: halve active threads each iteration
    .reg .u32 %s;
    mov.u32 %s, %blockDim_x;
REDUCE_LOOP:
    shr.u32 %s, %s, 1;                         // s = s / 2
    setp.eq.u32 %p_done, %s, 0;
    @%p_done bra REDUCE_DONE;

    .reg .pred %p_lt;
    setp.lt.u32 %p_lt, %tid_x, %s;
    @%p_lt {
        // a = shmem[tid]
        .reg .f32 %a, %b;
        ld.shared.f32 %a, [%shmem_addr];

        // b = shmem[tid + s]
        .reg .u64 %addr_b;
        add.u32 %i, %tid_x, %s;               // reuse %i as tid+s
        mul.wide.u32 %addr_b, %i, 4;
        ld.shared.f32 %b, [%addr_b];

        // a = a + b
        add.f32 %a, %a, %b;
        st.shared.f32 [%shmem_addr], %a;
    }
    bar.sync 0;
    bra REDUCE_LOOP;
REDUCE_DONE:

    // -----------------------------------------------------------------
    // Thread 0 writes mean (float16) to output
    // -----------------------------------------------------------------
    .reg .pred %p_thread0;
    setp.eq.u32 %p_thread0, %tid_x, 0;
    @%p_thread0 {
        // total sum is at shmem[0]
        ld.shared.f32 %local_sum, [shmem];
        // mean = total_sum / N
        .reg .f32 %mean;
        cvt.f32.u32 %f_n, %n;
        div.f32 %mean, %local_sum, %f_n;

        // convert to half (round‑to‑nearest‑even)
        .reg .f16 %h_mean;
        cvt.rn.f16.f32 %h_mean, %mean;

        // store result
        st.global.u16 [%out], %h_mean;
    }

    ret;
}
"""

# -------------------------------------------------------------------------
# Python wrapper that loads the PTX and launches the kernel
# -------------------------------------------------------------------------
class ModelNew:
    def __init__(self):
        # Load PTX module using the harness helper
        self.module = ptx_load(PTX_SOURCE)

    def forward(self, predictions, targets):
        """
        predictions: torch.Tensor of shape (batch_size,) dtype=torch.float16, device='cuda'
        targets:     torch.Tensor of same shape and dtype
        Returns: scalar torch.Tensor (float16) containing the mean hinge loss
        """
        assert predictions.is_cuda and targets.is_cuda
        assert predictions.dtype == torch.float16 and targets.dtype == torch.float16
        N = predictions.numel()

        # Allocate output scalar on the device
        out = torch.empty((), dtype=torch.float16, device='cuda')

        # Prepare kernel launch configuration
        block_dim = (1024, 1, 1)          # one block can process any size via striding
        grid_dim = (1, 1, 1)             # single block kernel

        # Kernel arguments: raw pointers and integer size
        args = [
            predictions.data_ptr(),
            targets.data_ptr(),
            out.data_ptr(),
            N
        ]

        # Launch the kernel via the harness
        ptx_launch(self.module, "hinge_loss_kernel", grid_dim, block_dim, args)

        return out
